#include "minimum-covering-slice.h"

std::optional<std::pair<std::size_t,std::size_t>> charm::v1n7::sublist::minimum_covering_slice(const std::vector<int>& values,const std::vector<int>& required){if(required.empty())return std::pair<std::size_t,std::size_t>{0,0};std::map<int,int> need,have;for(int value:required)++need[value];std::size_t satisfied=0,left=0,best_begin=0,best_end=0;bool found=false;for(std::size_t right=0;right<values.size();++right){int value=values[right];if(need.count(value)&&++have[value]==need[value])++satisfied;while(satisfied==need.size()){if(!found||right+1-left<best_end-best_begin){found=true;best_begin=left;best_end=right+1;}int drop=values[left++];if(need.count(drop)&&have[drop]--==need[drop])--satisfied;}}if(!found)return std::nullopt;return std::pair<std::size_t,std::size_t>{best_begin,best_end};}
